return [
  {
    json: {
      lane: 'gtm_engineering',
      query: '("GTM engineering" OR "go-to-market engineering" OR "outbound automation" OR "sales automation") lang:en -is:retweet',
      viral_likes_min: 25,
      viral_reposts_min: 5,
      viral_replies_min: 5
    }
  },
  {
    json: {
      lane: 'open_source_gtm',
      query: '("open source" OR open-source OR "open sourced" OR "open-sourced") ("GTM" OR outbound OR "cold email" OR CRM OR "sales automation" OR "lead enrichment") lang:en -is:retweet',
      viral_likes_min: 10,
      viral_reposts_min: 0,
      viral_replies_min: 0
    }
  }
];

const response = $json;
const laneInput = $('Define X Search Lanes').item.json;
const users = response.includes?.users ?? [];
const usersById = Object.fromEntries(users.map(u => [u.id, u]));

return (response.data ?? []).map(post => {
  const metrics = post.public_metrics ?? {};
  const author = usersById[post.author_id] ?? {};
  const urls = post.entities?.urls ?? [];
  const hasRepositoryLink = urls.some(({ expanded_url = '', url = '' }) =>
    /github\.com|gitlab\.com|codeberg\.org/i.test(`${expanded_url} ${url}`)
  );

  const likes = metrics.like_count ?? 0;
  const reposts = metrics.retweet_count ?? 0;
  const replies = metrics.reply_count ?? 0;
  const quotes = metrics.quote_count ?? 0;

  return {
    json: {
      platform: 'x',
      lane: laneInput.lane,
      post_id: post.id,
      dedupe_key: `x:${post.id}`,
      source_url: author.username
        ? `https://x.com/${author.username}/status/${post.id}`
        : `https://x.com/i/web/status/${post.id}`,
      author_handle: author.username ?? null,
      author_name: author.name ?? null,
      published_at: post.created_at ?? null,
      raw_text: post.text ?? '',
      likes,
      reposts,
      replies,
      quotes,
      engagement_score: likes + (reposts * 3) + (replies * 2) + (quotes * 2),
      has_repository_link: hasRepositoryLink,
      query_matched: laneInput.query,
      viral_likes_min: laneInput.viral_likes_min,
      viral_reposts_min: laneInput.viral_reposts_min,
      viral_replies_min: laneInput.viral_replies_min
    }
  };
});

return $input.all().filter(({ json: x }) => {
  if (!x.post_id || !(x.raw_text ?? '').trim()) return false;

  if (x.lane === 'open_source_gtm') {
    return x.has_repository_link ||
      x.likes >= x.viral_likes_min ||
      x.reposts >= x.viral_reposts_min ||
      x.replies >= x.viral_replies_min;
  }

  return x.likes >= x.viral_likes_min ||
    x.reposts >= x.viral_reposts_min ||
    x.replies >= x.viral_replies_min;
});

// Parse the AI response and prepare for Notion
const data = $input.first().json;
const choices = data.choices || [];
const message = choices[0]?.message?.content || '{}';

let parsed;
try {
  parsed = JSON.parse(message);
} catch (e) {
  parsed = {
    signal_type: 'Unknown',
    mechanic: '',
    why_it_works: '',
    relevance: 'Low',
    adaptation_hint: '',
    _raw: message
  };
}

return [{
  json: {
    source: $json.source,
    url: $json.url,
    ...parsed
  }
}];
